declarations.definition:
fun s x =>
  match x with
  | payment_domain.Write.PutPayment p =>
    { next := s.next, payments := H5iAppLib.upsert (fun x => x.id) p s.payments, refunds := s.refunds,
      events := s.events, refs := s.refs, merchants := s.merchants }
  | payment_domain.Write.PutRefund r =>
    { next := s.next, payments := s.payments, refunds := H5iAppLib.upsert (fun x => x.id) r s.refunds,
      events := s.events, refs := s.refs, merchants := s.merchants }
  | payment_domain.Write.PutEvent e =>
    { next := s.next, payments := s.payments, refunds := s.refunds,
      events := H5iAppLib.upsert (fun x => x.id) e s.events, refs := s.refs, merchants := s.merchants }
  | payment_domain.Write.PutRef r =>
    { next := s.next, payments := s.payments, refunds := s.refunds, events := s.events,
      refs := H5iAppLib.upsert (fun x => x.payment) r s.refs, merchants := s.merchants }
  | payment_domain.Write.SetCounter c =>
    { next := ↑c.next_id, payments := s.payments, refunds := s.refunds, events := s.events, refs := s.refs,
      merchants := s.merchants }
  | payment_domain.Write.PutMerchant c =>
    { next := s.next, payments := s.payments, refunds := s.refunds, events := s.events, refs := s.refs,
      merchants := H5iAppLib.upsert (fun x => x.merchant) c s.merchants }

